INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8cc8-7b7c-ae66-f21a57028440'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'The period P of a pendulum is directly proportional to the square root of its length L. If P increases by 25%, what is the percentage increase in L?', '56.25%', 'Since P is proportional to sqrt(L), L is proportional to P^2. If P increases by 25%, then L changes by 1.25^2 = 1.5625. So the increase in L is 56.25%.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.744Z'::timestamptz, '2026-08-15T07:36:12.744Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8cde-7bf9-a539-db60dc46ab03'::uuid, '019f9df7-a2a2-78ab-b1d6-52be9d287151'::uuid, 'The Great Pyramid has surface area 8.30 × 10^4 m^2 and volume 2.45 × 10^4 m^3. A similar replica has volume 9.22 × 10^-6 m^3. Estimate the surface area of the replica.', '4.33 × 10^-2 m^2', 'For similar solids, surface area scales with the square of the linear scale and volume scales with the cube. Use the volume ratio to find the linear scale, then square it and apply it to 8.30 × 10^4. This gives approximately 4.33 × 10^-2 m^2.', 'Hard', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.766Z'::timestamptz, '2026-08-15T07:36:12.766Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8d04-7ab9-a66a-cc53880b1cdb'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'The universal set is the integers from 0 to 10. Set A = {1, 4, 9} and set B = {1, 2, 4, 8}. Describe the elements of set A.', 'Perfect squares', 'The elements 1, 4 and 9 are the perfect squares in the universal set from 0 to 10.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.804Z'::timestamptz, '2026-08-15T07:36:12.804Z'::timestamptz) ON CONFLICT (id) DO NOTHING;